import React, { useState, useEffect, useRef } from "react";
import { Link, NavLink, useLocation, useSearchParams } from "react-router-dom";

// Импорт логотипов
import plLogo from "../../assets/leagues/premier-league.png";
import blLogo from "../../assets/leagues/bundesliga.png";
import saLogo from "../../assets/leagues/serie-a.png";
import pdLogo from "../../assets/leagues/la-liga.png";
import flLogo from "../../assets/leagues/ligue-1.png";

const leagues = [
  { code: null, name: "ВСЕ ЧЕМПИОНАТЫ", logo: null },
  { code: "Premier_League", name: "Premier League", logo: plLogo },
  { code: "La_Liga", name: "La Liga", logo: pdLogo },
  { code: "Serie_A", name: "Serie A", logo: saLogo },
  { code: "Bundesliga", name: "Bundesliga", logo: blLogo },
  { code: "Ligue_1", name: "Ligue 1", logo: flLogo },
];

function Header() {
  const [isLeagueOpen, setIsLeagueOpen] = useState(false);
  const [searchParams] = useSearchParams();
  const currentLeagueCode = searchParams.get("league");
  const location = useLocation();
  const dropdownRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsLeagueOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      setIsLeagueOpen(false);
    };
  }, [location]);

  const activeLeague =
    leagues.find((l) => l.code === currentLeagueCode) || leagues[0];

  return (
    <header className="bg-gray-950 border-b border-gray-900 sticky top-0 z-[100] w-full">
      <div className="container mx-auto px-4 h-24 flex items-center justify-between gap-2 md:gap-4">
        {/* ЛОГОТИП */}
        <Link to="/" className="flex-shrink-0">
          <span className="text-xl lg:text-2xl font-black tracking-tighter text-gradient-neuro-title uppercase italic">
            Neuro<span className="text-red-600">Predict</span>
          </span>
        </Link>

        {/* ЦЕНТРАЛЬНЫЙ ПОИСК */}
        <div className="flex-grow max-w-xs md:max-w-md relative">
          <input
            type="text"
            placeholder="Поиск..."
            className="w-full bg-gray-900 border border-gray-800 rounded-xl py-2 px-4 text-xs text-gray-300 focus:outline-none focus:border-red-600 transition-all"
          />
        </div>

        {/* ПРАВАЯ ЧАСТЬ */}
        <div className="flex items-center gap-2" ref={dropdownRef}>
          {/* КНОПКА ЕВРОКУБКОВ И СРАВНЕНИЯ */}
          <button className="flex items-center gap-2 px-3 py-2.5 bg-gray-900 border border-gray-800 rounded-xl hover:border-red-600 transition-all group shadow-lg">
            <svg
              className="w-5 h-5 text-yellow-500 group-hover:scale-110 transition-transform"
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <path
                fillRule="evenodd"
                d="M10 2a1 1 0 011 1v1.323l3.954 1.582 1.599-.8a1 1 0 01.894 1.79l-1.233.616 1.738 5.42a1 1 0 01-.285 1.05l-3.293 3.293a1 1 0 01-1.414 0l-3.293-3.293a1 1 0 01-.285-1.05l1.738-5.42-1.233-.616a1 1 0 01.894-1.79l1.599.8L9 4.323V3a1 1 0 011-1z"
                clipRule="evenodd"
              />
            </svg>
            <span className="hidden sm:block text-[10px] font-black uppercase text-gray-400 group-hover:text-white tracking-widest">
              Cups & H2H
            </span>
          </button>

          {/* ВЫБОР ЛИГИ */}
          <div className="relative">
            <button
              onClick={() => setIsLeagueOpen(!isLeagueOpen)}
              className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border-2 transition-all ${
                isLeagueOpen
                  ? "bg-red-600 border-red-600 shadow-red-500/20 shadow-xl"
                  : "bg-gray-900 border-gray-800 text-gray-300 hover:border-gray-600"
              }`}
            >
              <span className="hidden lg:block text-[10px] font-black uppercase tracking-widest">
                {activeLeague.code ? activeLeague.name : "Выбрать лигу"}
              </span>
              <svg
                className={`w-4 h-4 transition-transform ${isLeagueOpen ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="3"
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* ВЫПАДАЮЩИЙ СПИСОК С КРУПНЫМИ ИКОНКАМИ */}
            {isLeagueOpen && (
              <div className="absolute top-full right-0 mt-3 w-[280px] bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                <div className="flex flex-col p-2 space-y-1">
                  {leagues.map((league) => {
                    const isActive =
                      currentLeagueCode === league.code ||
                      (!currentLeagueCode && league.code === null);
                    return (
                      <NavLink
                        key={league.code || "all"}
                        to={league.code ? `/?league=${league.code}` : "/"}
                        className={`flex items-center gap-4 px-3 py-3 rounded-xl transition-all ${
                          isActive
                            ? "bg-red-600 text-white"
                            : "text-gray-400 hover:bg-gray-900 hover:text-white"
                        }`}
                      >
                        {/* КРУПНАЯ ИКОНКА */}
                        <div
                          className={`w-14 h-14 rounded-lg flex items-center justify-center flex-shrink-0 shadow-inner ${
                            isActive ? "bg-white/10" : "bg-white"
                          }`}
                        >
                          {league.logo ? (
                            <img
                              src={league.logo}
                              alt=""
                              className="w-10 h-10 object-contain"
                            />
                          ) : (
                            <span className="text-xs font-black text-yellow-500">
                              ALL
                            </span>
                          )}
                        </div>

                        <div className="flex flex-col">
                          <span
                            className={`text-xs font-black uppercase tracking-tight ${isActive ? "text-white" : ""}`}
                          >
                            {league.name}
                          </span>
                          {isActive && (
                            <span className="text-[9px] font-bold opacity-70 uppercase">
                              Выбрано
                            </span>
                          )}
                        </div>
                      </NavLink>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

export default Header;
